using System.IO;using UnityEngine;using UnityEngine.Rendering.Universal;public static class CaptureRailFree{public static object Main(){var original=GameObject.Find("Main Camera").GetComponent<Camera>();var go=new GameObject("Review capture");var cam=go.AddComponent<Camera>();cam.CopyFrom(original);cam.enabled=false;cam.transform.position=new Vector3(-75,0,-10);cam.orthographicSize=56;cam.aspect=2112f/1792f;cam.cullingMask=original.cullingMask&~(1<<5);var data=go.AddComponent<UniversalAdditionalCameraData>();data.renderType=CameraRenderType.Base;data.SetRenderer(0);data.renderPostProcessing=false;var rt=new RenderTexture(2112,1792,24);var old=RenderTexture.active;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(2112,1792,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,2112,1792),0,0);tex.Apply();File.WriteAllBytes("output/scene-review/rail-free-town.png",tex.EncodeToPNG());RenderTexture.active=old;cam.targetTexture=null;rt.Release();Object.DestroyImmediate(tex);Object.DestroyImmediate(rt);Object.DestroyImmediate(go);return "Captured final";}}


